<?php require __DIR__.'/../config/config.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){foreach(['site_name','tagline','male_premium_price','female_premium_price','upi_id','telegram_bot_token','telegram_chat_id','phonepe','gpay','paytm'] as $k){if(isset($_POST[$k])){db()->prepare('INSERT INTO settings(`key`,`value`) VALUES(?,?) ON DUPLICATE KEY UPDATE value=VALUES(value)')->execute([$k,$_POST[$k]]);}}if(!empty($_FILES['qr']['name'])&&$_FILES['qr']['error']===0){$ext=strtolower(pathinfo($_FILES['qr']['name'],PATHINFO_EXTENSION));if(in_array($ext,['png','jpg','jpeg','webp'])){$name='qr_'.time().'.'.$ext;move_uploaded_file($_FILES['qr']['tmp_name'],__DIR__.'/../uploads/'.$name);db()->prepare('UPDATE settings SET value=? WHERE `key`="qr_image"')->execute([$name]);}}$saved=true;}?>
<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="../assets/style.css"></head><body><main class="phone"><header><a href="index.php">←</a><b>Settings</b></header><section class="card"><form method="post" enctype="multipart/form-data"><input name="site_name" value="<?=h(setting('site_name'))?>" placeholder="Site Name"><input name="tagline" value="<?=h(setting('tagline'))?>"><h3>Premium Prices</h3><input name="male_premium_price" value="<?=h(setting('male_premium_price','199'))?>" placeholder="Male price"><input name="female_premium_price" value="<?=h(setting('female_premium_price','99'))?>" placeholder="Female price"><h3>Shared Payment Settings</h3><input name="upi_id" value="<?=h(setting('upi_id'))?>" placeholder="UPI ID"><input type="file" name="qr" accept="image/*"><input name="telegram_bot_token" value="<?=h(setting('telegram_bot_token'))?>" placeholder="Telegram Bot Token"><input name="telegram_chat_id" value="<?=h(setting('telegram_chat_id'))?>" placeholder="Telegram Chat ID"><label><input type="checkbox" name="phonepe" value="1" <?=setting('phonepe','1')?'checked':''?>> PhonePe</label><label><input type="checkbox" name="gpay" value="1" <?=setting('gpay','1')?'checked':''?>> GPay</label><label><input type="checkbox" name="paytm" value="1" <?=setting('paytm','1')?'checked':''?>> Paytm</label><button>Save Settings</button></form><?php if(isset($saved)):?><div class="success">Settings updated.</div><?php endif;?></section></main><script src="/rishtewale-protection.js"></script>
</body></html>
